import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.position.set(-2.5, 1.6, 0);
  root.scale.set(1, 1, 1);
  root.rotation.set(0, 0, 0);

  const timelines = [];
  const disposables = [];

  // Load GLB mesh for machined surface
  let glbScene = null;
  if (config.meshUrl && ctx.glbLoader) {
    try {
      const glb = ctx.glbLoader.load(config.meshUrl);
      if (glb && glb.scene) {
        glbScene = glb.scene;
        glbScene.traverse((node) => {
          if (node instanceof THREE.Mesh) {
            node.castShadow = true;
            node.receiveShadow = true;
          }
        });
        root.add(glbScene);
        disposables.push(glbScene);
      }
    } catch (error) {
      console.error('[StatTile] Failed to load GLB:', error);
    }
  }

  // Apply cinematic primitive: parallax-scroll
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    try {
      ctx.primitives['parallax-scroll'](root, {
        intensity: 0.25
      });
    } catch (error) {
      console.error('[StatTile] Failed to apply parallax-scroll:', error);
    }
  }

  // Interaction handlers
  const handlers = {};

  handlers.onHover = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    // Rise-in: move up 0.15 units over 0.7s with power3.out easing
    const tl = gsap.timeline();
    tl.to(root.position, {
      y: root.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(tl);
  };

  handlers.onUnhover = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    const tl = gsap.timeline();
    tl.to(root.position, {
      y: 1.6,
      duration: 0.7,
      ease: 'power3.out'
    });
    timelines.push(tl);
  };

  handlers.onClick = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    // Press-down effect: scale to 0.97 (120ms, back.out), then restore
    const tl = gsap.timeline();
    tl.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out'
    });
    tl.to(root.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.15,
      ease: 'back.out'
    });
    timelines.push(tl);
  };

  // Cleanup: dispose timelines and Three.js resources
  root.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    timelines.length = 0;

    disposables.forEach(obj => {
      obj.traverse((node) => {
        if (node instanceof THREE.Mesh) {
          if (node.geometry) {
            node.geometry.dispose();
          }
          if (node.material) {
            if (Array.isArray(node.material)) {
              node.material.forEach(m => m.dispose());
            } else {
              node.material.dispose();
            }
          }
        }
      });
    });
  };

  root.userData.handlers = handlers;

  return root;
}
